const str = () => { const n = r(9); let s=''; for (let i=0;i<n;i++) s += chars[r(chars.length)]; return s; };
const same = (a,b) => Object.is(a,b) || JSON.stringify(a)===JSON.stringify(b);
let fails = [];
const check = (label, a, b, input) => { if (!same(a,b)) fails.push({label, input, a, b}); };
// examples
for (const r0 of [{id:1,name:'jung',age:24},{id:8,name:'choi',age:47}]) check('pub', O.publicFields(r0), N.publicFields(r0), r0);
const ta = [[{id:9,name:'kim',age:45},{id:6,name:'park',age:30},{id:9,name:'lee',age:49}]];
check('total', O.totalAge(ta[0]), N.totalAge(ta[0]), ta[0]);
for (const t of ['92858+99', '.72e']) check('parse', O.parseAmount(t), N.parseAmount(t), t);
// random
const N_ITER = 200000;
let pubCount=0, totCount=0, parseCount=0;
for (let i=0;i<N_ITER;i++){
  const rr=row(); check('pub', O.publicFields(rr), N.publicFields(rr), rr); pubCount++;
  const len=r(13); const arr=Array.from({length:len},row);
  check('total', O.totalAge(arr), N.totalAge(arr), arr); totCount++;
  const s=str(); check('parse', O.parseAmount(s), N.parseAmount(s), s); parseCount++;
}
console.log(JSON.stringify({pub:pubCount,total:totCount,parse:parseCount,failures:fails.length, sample: fails.slice(0,5)}, null, 1));
console.log('parse samples:', ['92858+99','.72e','1e5','0x1f',' 12 ','-0x1','+0x1f','0b101','0o17','','-','e','1 2','.5','5.','1e+3'].map(s=>[s,O.parseAmount(s),N.parseAmount(s)]));
console.log('empty total:', O.totalAge([]), N.totalAge([]));
